#!/usr/bin/env python3\n\"\"\"\nNexus Prime System Test\nQuick verification that all components are working\n\"\"\"\n\nimport asyncio\nimport sys\nimport os\nsys.path.append(os.path.join(os.path.dirname(__file__), '..', 'backend'))\n\nasync def test_system():\n    print(\"🚀 Testing Nexus Prime System Components...\")\n    print(\"=\" * 50)\n    \n    # Test 1: Import all services\n    try:\n        from app.services.rca_engine import rca_engine\n        from app.services.notifications import notification_service\n        from app.services.websocket_manager import ws_manager\n        from app.services.remediation import remediation_service\n        print(\"✅ All services imported successfully\")\n    except Exception as e:\n        print(f\"❌ Service import failed: {e}\")\n        return False\n    \n    # Test 2: Check configuration\n    try:\n        from app.core.config import settings\n        print(f\"✅ Configuration loaded\")\n        print(f\"   - Mock mode: {settings.is_mock_mode()}\")\n        print(f\"   - Azure OpenAI: {'✅' if settings.AZURE_OPENAI_API_KEY else '❌'}\")\n        print(f\"   - Cosmos DB: {'✅' if settings.COSMOS_ENDPOINT else '❌'}\")\n    except Exception as e:\n        print(f\"❌ Configuration failed: {e}\")\n        return False\n    \n    # Test 3: Test RCA Engine\n    try:\n        test_incident = {\n            \"title\": \"Test Incident\",\n            \"summary\": \"System test incident\",\n            \"severity\": \"SEV3\",\n            \"created_at\": \"2024-01-01T00:00:00Z\"\n        }\n        result = rca_engine.analyze(test_incident)\n        print(f\"✅ RCA Engine working (provider: {rca_engine.provider})\")\n    except Exception as e:\n        print(f\"❌ RCA Engine failed: {e}\")\n        return False\n    \n    # Test 4: Test WebSocket Manager\n    try:\n        stats = ws_manager.get_connection_stats()\n        print(f\"✅ WebSocket Manager working ({stats['total_connections']} connections)\")\n    except Exception as e:\n        print(f\"❌ WebSocket Manager failed: {e}\")\n        return False\n    \n    # Test 5: Test Remediation Service\n    try:\n        test_steps = [\"Restart service api\", \"Scale deployment to 3 replicas\"]\n        result = await remediation_service.execute_remediation_steps(\"test-123\", test_steps)\n        print(f\"✅ Remediation Service working (dry run: {remediation_service.dry_run})\")\n    except Exception as e:\n        print(f\"❌ Remediation Service failed: {e}\")\n        return False\n    \n    print(\"\\n🎉 All system components are working correctly!\")\n    print(\"\\n📋 Next Steps:\")\n    print(\"   1. Start backend: uvicorn app.main:app --reload --port 8000\")\n    print(\"   2. Start frontend: cd frontend && npm run dev\")\n    print(\"   3. Test with: python scripts/enhanced_seed_data.py --quick\")\n    \n    return True\n\nif __name__ == \"__main__\":\n    success = asyncio.run(test_system())\n    sys.exit(0 if success else 1)\n